import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, readdirSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { generateSchemas } from "./generate-schemas.mjs";

const GENERATED = "src/api/generated";

// Compare generated bytes with the working copy. Comparing with Git HEAD
// incorrectly rejects a synchronized client whenever its schema is being edited.
const directory = mkdtempSync(join(tmpdir(), "contractor-public-client-"));
try {
  execFileSync(
    "openapi-typescript",
    [
      "../api/openapi/contractor-public-v1.yaml",
      "-o",
      join(directory, "public.ts"),
    ],
    { stdio: "inherit" },
  );
  await generateSchemas(directory);
  const expected = readdirSync(directory).sort();
  const actual = readdirSync(GENERATED).sort();
  const stale = [
    ...expected.filter(
      (name) =>
        !actual.includes(name) ||
        !readFileSync(join(directory, name)).equals(
          readFileSync(join(GENERATED, name)),
        ),
    ),
    ...actual.filter((name) => !expected.includes(name)),
  ];
  if (stale.length > 0) {
    throw new Error(
      `Generated contract files are stale (${stale.join(", ")}). Run pnpm generate.`,
    );
  }
} finally {
  rmSync(directory, { recursive: true, force: true });
}
